+    chat.handle_codex_event(Event {
+        id: "sub-xyz".into(),
+        msg: EventMsg::PatchApplyEnd(PatchApplyEndEvent {
+            call_id: "call-1".into(),
+            turn_id: "turn-call-1".into(),
+            stdout: String::from("ok"),
+            stderr: String::new(),
