+async fn apply_patch_request_shows_diff_summary() -> anyhow::Result<()> {
+    let (mut chat, mut rx, _op_rx) = make_chatwidget_manual(/*model_override*/ None).await;
+
+    // Ensure we are in OnRequest so an approval is surfaced
+    chat.config
+        .permissions
